/* Native Canvas financial dashboard; no chart library or SVG output. */
let flowIndex=-1,growthVisible=true,budgetFocus=-1,assetMode='assets',assetIndex=-1,heatDay=4;
const dashboardCanvases=new Map();
const ALLOCATION_HEIGHT=160;
let assetPinnedIndex=-1,dailyStart=0,budgetInteraction=null,receiptPage=0,receiptDate="";
let allocationTransition=null,allocationParent=null,budgetExpanded=false;
const financialColors=['#78906d','#b97d61','#6e929b','#b19a56','#927eaa','#b77380','#67857d','#a58368','#858aa8','#a1a56a','#879d92','#a28595'];
const palette={ink:'#344638',muted:'#748171',line:'#e2daca',expense:'#8b403b',income:'#315d47',balance:'#b49859',growth:'#85769b'};
// Canvas and SVG marks read the same semantic colors as all DOM amounts and controls.
if(typeof getComputedStyle==='function'){
  const theme=getComputedStyle(document.documentElement);
  palette.income=theme.getPropertyValue('--ui-positive').trim()||palette.income;
  palette.expense=theme.getPropertyValue('--ui-negative').trim()||palette.expense;
}
const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));
function monthDays(m=month){return new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate();}
function elapsedDays(){const days=monthDays(),latest=Math.max(0,...monthly().map(t=>Number(t.date.slice(8))));return month<TODAY.slice(0,7)?days:month===TODAY.slice(0,7)?Math.min(days,Math.max(Number(TODAY.slice(8)),latest)):Math.min(days,latest);}
function dailyFacts(){return Array.from({length:monthDays()},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0');let income=0,expense=0;for(const t of monthly().filter(t=>t.date===date)){if(t.type==='income')income+=t.amount;if(t.type==='expense')expense+=t.amount;if(t.type==='refund')expense-=t.amount;}return{date,label:(i+1)+'日',income,expense,balance:income-expense};});}
function flowThrough(m){const d=new Date(m+'-01T00:00:00Z'),end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).toISOString().slice(0,10);return m===TODAY.slice(0,7)?m+'-'+String(Math.min(monthDays(m),Math.max(Number(TODAY.slice(8)),...activeTx().filter(t=>t.date.startsWith(m)).map(t=>Number(t.date.slice(8)))))).padStart(2,'0'):end;}
function flowFacts(){const start=new Date(month+'-01T00:00:00Z');return Array.from({length:6},(_,i)=>{const d=new Date(start);d.setUTCMonth(d.getUTCMonth()-5+i);const m=d.toISOString().slice(0,7),t=totals(m);return{date:m,label:Number(m.slice(5))+'月',...t,balance:t.income-t.expense,assets:netWorth(flowThrough(m))};});}
const accountGroups=[{id:'banks',name:'銀行',group:'bank',color:'#78906d'},{id:'wallets',name:'電子支付',group:'ewallet',color:'#6e929b'},{id:'cash-group',name:'現金',group:'cash',color:'#b19a56'}];
function accountGroup(a){return a.kind==='cash'?'cash':a.kind==='ewallet'?'ewallet':'bank';}
function groupedAccounts(group){return state.accounts.filter(a=>a.kind!=='card'&&accountGroup(a)===group).map(a=>({id:a.id,name:a.name,value:Math.max(0,balance(a)),kind:'account'})).filter(a=>a.value>0).sort((a,b)=>b.value-a.value).map((a,i)=>({...a,color:financialColors[i%financialColors.length]}));}
function rootAssetFacts(){return [...accountGroups.map(g=>({...g,value:groupedAccounts(g.group).reduce((n,a)=>n+a.value,0),kind:'group'})),{id:'investments',name:'投資',value:investmentTotal(),kind:'investment',color:'#b97d61'}].filter(i=>i.value>0).sort((a,b)=>b.value-a.value);}
function holdingFacts(){return state.holdings.map(h=>({id:h.id,name:h.id,value:h.qty*h.price,kind:'holding'})).filter(h=>h.value>0).sort((a,b)=>b.value-a.value).map((h,i)=>({...h,color:financialColors[i%financialColors.length]}));}
function accountAssetFacts(){return allocationParent?groupedAccounts(allocationParent.group):[];}
function assetFacts(){return assetMode==='holdings'?holdingFacts():assetMode==='account'?accountAssetFacts():rootAssetFacts();}
function allocationTotal(){return assetFacts().reduce((n,a)=>n+a.value,0);}
function allocationName(){return assetMode==='holdings'?'全部持股':assetMode==='account'?'全部帳戶':'全部資產';}
function allocationTiles(w,h){return splitTiles(assetFacts(),0,0,w,h);}
function dayTransactions(day=heatDay){const date=month+'-'+String(day).padStart(2,'0');return recent(monthly().filter(t=>t.date===date));}
const DAILY_RECEIPT_SIZE=6;
const DAILY_RECEIPT_GROUP_SIZE=6;
function dailyReceiptWindow(day=heatDay){const date=month+'-'+String(day).padStart(2,'0'),all=dayTransactions(day);if(receiptDate!==date){receiptDate=date;receiptPage=0;}const pages=Math.max(1,Math.ceil(all.length/DAILY_RECEIPT_SIZE));receiptPage=clamp(receiptPage,0,pages-1);const from=receiptPage*DAILY_RECEIPT_SIZE;return{rows:all.slice(from,from+DAILY_RECEIPT_SIZE),total:all.length,page:receiptPage,pages,from:all.length?from+1:0,to:Math.min(all.length,from+DAILY_RECEIPT_SIZE)};}
function dailyReceipt(t){
 const label={expense:'支出',income:'收入',refund:'退款',transfer:'轉帳',investment:'投資'}[t.type]||'紀錄',accountLabel=(account(t.account)?.name||'帳戶')+(t.to?' → '+(account(t.to)?.name||'帳戶'):''),incoming=transactionIncoming(t),tone=t.dividend||t.type==='investment'?'investment':t.type==='transfer'?'transfer':incoming?'positive':'negative',amount=(t.type==='transfer'?'':incoming?'+':'−')+(state.privacy?'••••':money(t.amount).length>8?(t.amount>=1e12?(t.amount/1e12).toLocaleString('zh-TW',{maximumFractionDigits:1})+'兆':compactMoney(t.amount)):money(t.amount)),size=money(t.amount).length>8?'receipt-amount-small ':'';
 return `<button class="daily-receipt" style="--receipt-tone:var(--ui-${tone})" data-action="tx-detail" data-id="${esc(t.id)}" aria-label="${esc(label+' '+(t.type==='transfer'?'':incoming?'+':'−')+overviewMoney(t.amount)+'，'+(t.note||t.category)+'，'+t.category+'，'+accountLabel)}"><span class="receipt-glyph" aria-hidden="true">${journalIcon(t)}</span><span class="receipt-copy"><strong class="receipt-note">${esc(t.note||t.category)}</strong><b class="${size}${incoming?'positive':['expense','investment'].includes(t.type)?'expense-amount':''}">${amount}</b></span></button>`;
}
function dailyReceiptPosition(view){return view.total<=DAILY_RECEIPT_SIZE?`${view.total} 筆`:`${view.from}${view.to>view.from?'-'+view.to:''} / ${view.total}`;}
function dailyDetails(day=heatDay){
 const view=dailyReceiptWindow(day),d=dailyFacts()[day-1];
 return `<div class="daily-details-head"><h3>${Number(month.slice(5))} 月 ${day} 日</h3>${view.pages>1?`<button id="daily-page-select" class="daily-page-position" data-action="dash-receipt-page-open" aria-label="選擇明細頁次，第 ${view.page+1} 頁，共 ${view.pages} 頁"><span id="daily-receipt-position">${dailyReceiptPosition(view)}</span></button>`:`<span id="daily-receipt-position">${dailyReceiptPosition(view)}</span>`}<div class="daily-day-total"><span>${d.expense<0?'淨退款':'支出'}</span><strong class="${d.expense<0?'positive':'expense-amount'}" aria-label="${overviewCurrency(d.expense)}">${overviewMoney(Math.abs(d.expense))}</strong></div></div>${view.total?`<div class="daily-receipts${view.pages>1?' paged':''}" tabindex="0" role="region" aria-roledescription="輪播" aria-label="當日紀錄，六筆一頁，左右滑動或按方向鍵換頁，第 ${view.page+1} 頁，共 ${view.pages} 頁"><div class="daily-receipt-group">${view.rows.map(dailyReceipt).join('')}</div></div>`:'<div class="daily-empty">當天沒有紀錄</div>'}`;
}
function setDailyReceiptPage(index){if(!Number.isFinite(index))return;const view=dailyReceiptWindow(),next=clamp(Math.floor(index),0,view.pages-1);if(next===view.page)return;receiptPage=next;$('#daily-details').innerHTML=dailyDetails();$('#daily-page-select')?.focus?.();}
function openDailyReceiptPages(trigger){
  const view=dailyReceiptWindow();
  showPickerPage({kind:'pagination',title:'選擇明細頁次',trigger,render:()=>`<div class="receipt-page-options">${Array.from({length:view.pages},(_,i)=>`<button type="button" data-action="dash-receipt-page-select" data-index="${i}" aria-pressed="${i===view.page}" class="${i===view.page?'selected':''}" aria-label="第 ${i+1} 頁">${i+1}</button>`).join('')}</div>`});
}


function splitTiles(items,x,y,w,h){
  if(!items.length||w<=0||h<=0)return[];const minimum=Math.min(...items.filter(i=>i.value>0).map(i=>i.value));if(!Number.isFinite(minimum))return[];
  const weighted=items.filter(i=>i.value>0).map(i=>({...i,displayWeight:1+Math.log2(i.value/minimum)/6})),total=weighted.reduce((n,i)=>n+i.displayWeight,0);
  const remaining=weighted.map(i=>({...i,area:i.displayWeight/total*w*h})),tiles=[];let bx=x,by=y,bw=w,bh=h;
  const worst=(row,side)=>{if(!row.length)return Infinity;const a=row.map(i=>i.area),sum=a.reduce((n,v)=>n+v,0);return Math.max(side*side*Math.max(...a)/(sum*sum),(sum*sum)/(side*side*Math.min(...a)));};
  function lay(row){const area=row.reduce((n,i)=>n+i.area,0);if(bw>=bh){const cw=area/bh;let cy=by;for(const item of row){const ch=item.area/cw;tiles.push({...item,x:bx,y:cy,w:cw,h:ch});cy+=ch;}bx+=cw;bw=Math.max(0,bw-cw);}else{const ch=area/bw;let cx=bx;for(const item of row){const cw=item.area/ch;tiles.push({...item,x:cx,y:by,w:cw,h:ch});cx+=cw;}by+=ch;bh=Math.max(0,bh-ch);}}
  let row=[];while(remaining.length){const next=remaining[0],side=Math.min(bw,bh);if(!row.length||worst([...row,next],side)<=worst(row,side)){row.push(remaining.shift());}else{lay(row);row=[];}}if(row.length)lay(row);return tiles;
}
function roundBox(ctx,x,y,w,h,r=5){r=Math.max(0,Math.min(r,w/2,h/2));ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();}
function shortLabel(ctx,text,width){if(width<=0)return '';if(ctx.measureText(text).width<=width)return text;let value=text;while(value.length&&ctx.measureText(value+'…').width>width)value=value.slice(0,-1);return value?value+'…':'';}
function destroyDashboard(){budgetInteraction=null;for(const chart of dashboardCanvases.values())chart.dispose();dashboardCanvases.clear();}
function mountPlot(id,height,draw,duration=520){
  const canvas=$('#'+id),ctx=canvas?.getContext?.('2d');if(!ctx)return null;
  const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;let width=300,frame=0,dead=false,observer;const cleanup=[];
  function render(animated=false){if(dead)return;if(frame)cancelAnimationFrame(frame);const now=performance.now();const tick=time=>{if(dead)return;const p=animated&&!reduced?Math.min(1,(time-now)/duration):1;ctx.clearRect(0,0,width,height);draw(ctx,width,height,1-Math.pow(1-p,3));if(p<1)frame=requestAnimationFrame(tick);else frame=0;};if(animated&&!reduced)frame=requestAnimationFrame(tick);else tick(now+duration);}
  function resize(){width=Math.max(120,canvas.getBoundingClientRect().width||300);const dpr=Math.min(3,window.devicePixelRatio||1);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);canvas.style.height=height+'px';ctx.setTransform(dpr,0,0,dpr,0,0);render();}
  if(typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(resize);observer.observe(canvas);}else window.addEventListener('resize',resize);
  const chart={canvas,render,width:()=>width,cleanup:fn=>cleanup.push(fn),dispose(){dead=true;cleanup.forEach(fn=>fn());if(frame)cancelAnimationFrame(frame);observer?.disconnect();if(!observer)window.removeEventListener?.('resize',resize);}};
  dashboardCanvases.set(id,chart);resize();render(true);return chart;
}
function plotGesture(canvas,select){let dragging=false,sx=0,sy=0;let pressedAt=0;const gesture={dragged:false,held:false};const local=e=>{const r=canvas.getBoundingClientRect();select((e.clientX-r.left)/(r.width||1),(e.clientY-r.top)/(r.height||1),e);};canvas.addEventListener('pointerdown',e=>{dragging=true;gesture.dragged=false;gesture.held=false;pressedAt=performance.now();sx=e.clientX;sy=e.clientY;canvas.setPointerCapture?.(e.pointerId);local(e);});canvas.addEventListener('pointermove',e=>{if(dragging&&Math.hypot(e.clientX-sx,e.clientY-sy)>8)gesture.dragged=true;if(dragging||e.pointerType==='mouse')local(e);});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>{if(event==='pointerup')gesture.held=performance.now()-pressedAt>=260;dragging=false;});return gesture;}

function flowLabel(d){return d.date===TODAY.slice(0,7)?d.label+' · '+Number(flowThrough(d.date).slice(8))+'日止':d.label;}
function allocationStatus(){return assetMode==='assets'?'':'返回資產';}
function allocationContext(){return assetMode==='holdings'?'投資':assetMode==='account'?(allocationParent?.name||'帳戶')+' · 帳戶':'資產';}

function canvasDashboard(){
  const flow=flowFacts();flowIndex=flowIndex<0?flow.length-1:clamp(flowIndex,0,flow.length-1);const f=flow[flowIndex],b=state.budgets[0],v=spent(b.category),assets=assetFacts();assetIndex=clamp(assetIndex,-1,Math.max(-1,assets.length-1));const a=assets[assetIndex],day=clamp(heatDay,1,monthDays());heatDay=day;
  return `<div class="finance-dashboard"><section class="heatmap-section"><div class="dash-heading"><h2>每日紀錄</h2><span id="daily-week-total">本週 ${overviewCurrency(dailyWeekTotal(dailyWeekStart(day)))}</span></div><div class="daily-week-nav"><button id="daily-prev" data-action="dash-week-prev" aria-label="上一週">‹</button><span id="daily-week-label">${dailyWeekLabel(dailyWeekStart(day))}</span><button id="daily-next" data-action="dash-week-next" aria-label="下一週">›</button></div><div id="daily-calendar" class="daily-calendar" role="group" aria-label="週一到週日，選擇日期查看當天紀錄">${dailyCalendar(dailyWeekStart(day))}</div><div class="activity-legend"><span><i class="expense"></i>支出</span><span><i class="income"></i>收入</span><span><i class="transfer"></i>轉帳</span><span><i class="investment"></i>投資</span></div><div id="daily-details" class="daily-details" aria-live="polite">${dailyDetails(day)}</div></section>${investmentTodayChart()}<section class="spending-budget-section${v>b.limit?' is-over':''}"><div class="dash-heading"><h2>支出與預算</h2><div class="spending-actions"><button id="budget-all" data-action="dash-budget-all" ${budgetFocus<0?'hidden':''}>整體</button><button class="budget-edit" data-action="dash-budget-edit" aria-label="編輯本月總預算">調整</button></div></div><div class="spending-summary"><div><span id="spending-label">本月支出</span><strong id="spending-used">${overviewCurrency(v)}</strong></div><div class="spending-remaining"><span id="budget-caption">${v>b.limit?'超出':'剩餘'}預算</span><span class="budget-values"><strong id="budget-remaining">${overviewCurrency(Math.abs(b.limit-v))}</strong><small id="budget-limit" class="budget-limit">／ ${overviewMoney(b.limit)}</small></span></div></div><div id="budget-inspection" class="budget-inspection">${budgetInspection()}</div></section><section class="allocation-section"><div class="dash-heading"><h2>財務分布</h2><strong id="asset-amount" class="allocation-value">${a?overviewCurrency(a.value):overviewCurrency(allocationTotal())}</strong></div><div class="allocation-context-row"><span class="allocation-selection"><span id="allocation-context">${esc(allocationContext())}</span><span id="asset-name">${a?esc(a.name):esc(allocationName())}</span></span><div class="allocation-context-actions"><button id="allocation-all" data-action="dash-asset-all" ${assetIndex<0?'hidden':''}>全部</button><button id="allocation-status" data-action="dash-asset-back" ${assetMode==='assets'?'hidden':''}>${allocationStatus()}</button></div></div><canvas id="allocation-canvas" tabindex="0" role="slider" aria-label="滑過、拖曳或長按區塊查看金額，輕點展開或收合，左右鍵選取" aria-valuemin="0" aria-valuemax="${assets.length}" aria-valuenow="${assetIndex+1}"></canvas></section><section class="flow-section"><div class="dash-heading"><h2>收支對照</h2><span>近六個月</span></div><div class="flow-period-row"><span id="flow-period">${flowLabel(f)}</span><span>結餘 <b id="flow-balance" class="${f.balance<0?'negative':'positive'}">${overviewCurrency(f.balance)}</b></span></div><div class="flow-summary"><div><span><i class="income-dot"></i>收入</span><strong id="flow-income">${overviewCurrency(f.income)}</strong></div><div><span><i class="expense-dot"></i>支出</span><strong id="flow-expense">${overviewCurrency(f.expense)}</strong></div></div><div class="flow-growth"><button data-action="dash-growth" aria-pressed="${growthVisible}" class="${growthVisible?'active':''}"><i></i>淨資產線</button><strong id="growth-amount" ${growthVisible?'':'hidden'}>${overviewCurrency(f.assets)}</strong></div><canvas id="flow-canvas" tabindex="0" role="slider" aria-label="拖曳查看每月收支與淨資產，左右鍵切換月份" aria-valuemin="1" aria-valuemax="${flow.length}" aria-valuenow="${flowIndex+1}" aria-valuetext="${f.label} 收入 ${overviewCurrency(f.income)} 支出 ${overviewCurrency(f.expense)}${growthVisible?' 淨資產 '+overviewCurrency(f.assets):''}"></canvas><div id="flow-axis" class="flow-axis">${flowAxis()}</div></section></div>`;
}
function flowAxis(){const data=flowFacts();return data.map((d,i)=>`<button data-action="dash-flow-select" data-index="${i}" style="left:calc(${(i+.5)/data.length*100}% + ${26-56*(i+.5)/data.length}px)" class="${i===flowIndex?'active':''}">${d.label}</button>`).join('');}
function flowGeometry(w,h){const data=flowFacts(),metrics=['income','expense'],all=data.flatMap(d=>metrics.map(m=>d[m])),min=Math.min(0,...all),max=Math.max(1,...all),assetMin=Math.min(...data.map(d=>d.assets)),assetMax=Math.max(...data.map(d=>d.assets)),padding=Math.max((assetMax-assetMin)*.15,1000);return{data,metrics,left:26,right:w-30,top:12,bottom:h-12,min,max,assetMin:assetMin-padding,assetMax:assetMax+padding};}
function drawFlow(ctx,w,h,p){
  const g=flowGeometry(w,h),{data,metrics,left,right,top,bottom,min,max,assetMin,assetMax}=g,y=v=>bottom-(v-min)/(max-min)*(bottom-top),assetY=v=>bottom-(v-assetMin)/(assetMax-assetMin)*(bottom-top),baseline=y(0),slot=(right-left)/data.length,bw=Math.max(2,Math.min(14,slot*(metrics.length===1?.55:.25))),gap=Math.max(2,Math.min(5,slot*.09));
  ctx.font='8px "Noto Sans TC",sans-serif';ctx.textBaseline='middle';
  for(let i=0;i<3;i++){const gy=top+(bottom-top)*i/2;ctx.strokeStyle=palette.line;ctx.lineWidth=.7;ctx.setLineDash([2,5]);ctx.beginPath();ctx.moveTo(left-3,gy);ctx.lineTo(right+3,gy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=palette.muted;ctx.textAlign='right';ctx.fillText(((max-(max-min)*i/2)/10000).toFixed(1),left-7,gy);if(growthVisible){ctx.fillStyle=palette.growth;ctx.textAlign='left';ctx.fillText(((assetMax-(assetMax-assetMin)*i/2)/10000).toFixed(1),right+7,gy);}}
  ctx.textBaseline='alphabetic';const selected=clamp(flowIndex,0,data.length-1);roundBox(ctx,left+selected*slot+1,1,Math.max(1,slot-2),h-1,7);ctx.fillStyle='#ded8c545';ctx.fill();
  data.forEach((d,i)=>{const cx=left+(i+.5)*slot,phase=clamp((p-i/data.length*.16)/.84,0,1);metrics.forEach((metric,j)=>{const value=d[metric],barY=baseline+(y(value)-baseline)*phase,height=Math.abs(baseline-barY),bx=metrics.length===1?cx-bw/2:cx+(j===0?-bw-gap/2:gap/2),color=palette[metric];ctx.globalAlpha=1;ctx.fillStyle=color;if(height>.05){roundBox(ctx,bx,Math.min(baseline,barY),bw,height,Math.min(4,bw/2));ctx.fill();}else{ctx.beginPath();ctx.arc(bx+bw/2,baseline,Math.min(1.5,bw/2),0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;});});
  ctx.strokeStyle='#b5b09f';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(left-3,baseline);ctx.lineTo(right+3,baseline);ctx.stroke();
  if(growthVisible){ctx.save();ctx.beginPath();ctx.rect(left-3,0,(right-left+6)*p,h);ctx.clip();ctx.strokeStyle=palette.growth;ctx.lineWidth=2;ctx.lineJoin='round';ctx.beginPath();data.forEach((d,i)=>{const x=left+(i+.5)*slot,py=assetY(d.assets);if(i)ctx.lineTo(x,py);else ctx.moveTo(x,py);});ctx.stroke();data.forEach((d,i)=>{const x=left+(i+.5)*slot,py=assetY(d.assets);ctx.beginPath();ctx.arc(x,py,i===selected?4:2.5,0,Math.PI*2);ctx.fillStyle='#f7f2e7';ctx.fill();ctx.lineWidth=i===selected?2:1.5;ctx.strokeStyle=palette.growth;ctx.stroke();});ctx.restore();}
}
// Allocate the smallest positive item first; fix undersized items at their floor,
// then distribute the remaining room proportionally among the larger items.
function minimumSizes(values,total,preferred){const sizes=values.map(()=>0),order=values.map((value,index)=>({value:Math.max(0,value),index})).filter(i=>i.value>0).sort((a,b)=>a.value-b.value);if(!order.length||total<=0)return sizes;const floor=Math.min(preferred,total/order.length);let room=total,weight=order.reduce((n,i)=>n+i.value,0);for(let i=0;i<order.length;i++){const item=order[i],ideal=room*item.value/weight;if(ideal<floor-1e-9){sizes[item.index]=floor;room-=floor;weight-=item.value;}else{for(const rest of order.slice(i))sizes[rest.index]=room*rest.value/weight;break;}}return sizes;}
function budgetInspection(){return `<canvas id="budget-canvas" tabindex="0" role="slider" aria-label="各分類支出與剩餘預算；點選色段查看金額，點空白或按 Escape 返回整體" aria-valuemin="0" aria-valuemax="${budgetBuckets().length}" aria-valuenow="${budgetFocus+1}"></canvas><div class="budget-scale" aria-label="總預算使用率"><span class="scale-zero">0</span><span id="budget-marker" class="budget-marker"><i></i><b id="budget-percent"></b></span><span class="scale-full">100</span></div>`;}
function budgetUsage(){const limit=state.budgets[0].limit,used=spent(state.budgets[0].category);return limit>0?used/limit*100:used>0?null:0;}

function budgetBuckets(){
  const names=new Set([...managedCategories('expense',true).map(c=>c.name),...state.budgets.slice(1).map(b=>b.category),...monthly().filter(t=>['expense','refund'].includes(t.type)).map(t=>t.category)]);
  return [...names].map(name=>{const budget=state.budgets.slice(1).find(b=>b.category===name),c=categoryByName(name,'expense');return{id:budget?.id||name,category:name,limit:budget?budget.limit:null,used:spent(name),color:c?.color||'#858aa8'};}).filter(b=>b.used!==0||b.limit!==null).sort((a,b)=>b.used-a.used);
}
const BUDGET_HEIGHT=52;

function budgetRegions(w,h){const buckets=budgetBuckets(),used=Math.max(0,spent(state.budgets[0].category)),limit=state.budgets[0].limit,ratio=limit>0?clamp(used/limit,0,1):used>0?1:0,total=w-4,usedWidth=total*ratio,items=buckets.map((b,i)=>({...b,index:i,value:Math.max(0,b.used)})),sizes=minimumSizes(items.map(b=>b.value),usedWidth,28);let x=2;const regions=items.map((b,i)=>{const r={...b,x,y:8,w:sizes[i],h:28};x+=sizes[i];return r;});regions.push({id:'available',index:-1,category:'剩餘',value:Math.max(0,limit-used),color:'#e4ded0',x:2+usedWidth,y:8,w:total-usedWidth,h:28});return regions;}
function budgetHit(x,y,w,h){if(x<0||x>w||y<0||y>h)return null;if(y<5||y>43)return -1;return budgetRegions(w,h).find(r=>r.w>0&&x>=r.x&&x<r.x+r.w)?.index??-1;}
function drawBudget(ctx,w,h,p){const regions=budgetRegions(w,h);ctx.save();roundBox(ctx,2,8,w-4,28,7);ctx.clip();ctx.fillStyle='#e4ded0';ctx.fillRect(2,8,w-4,28);for(const r of regions){ctx.globalAlpha=budgetFocus<0||r.index===budgetFocus?1:.4;ctx.fillStyle=r.color;ctx.fillRect(r.x,8,r.w*p,28);}ctx.restore();const selected=regions.find(r=>r.index===budgetFocus&&r.w>0);if(budgetFocus>=0&&selected){const x=selected.x+selected.w/2;ctx.fillStyle=selected.color;ctx.beginPath();ctx.moveTo(x-3,43);ctx.lineTo(x+3,43);ctx.lineTo(x,39);ctx.closePath();ctx.fill();}}
function budgetSummary(){const b=budgetBuckets()[budgetFocus],total=state.budgets[0],used=b?b.used:spent(total.category),limit=b?b.limit:total.limit,negative=budgetBuckets().reduce((n,b)=>n+Math.min(0,b.used),0);return{label:b?b.category:'本月支出',used,limit,caption:limit===null?'分類預算':used>limit?'超出預算':'剩餘預算',remaining:limit===null?null:Math.abs(limit-used),status:b?(limit===null?'未設定分類預算':totals().expense>0?'占本月支出 '+(used/totals().expense*100).toFixed(1)+'%':'本月無淨支出'):(negative<0?'含退款抵扣 '+overviewCurrency(-negative):'')};}
function refreshBudget(){const buckets=budgetBuckets();budgetFocus=clamp(budgetFocus,-1,buckets.length-1);const summary=budgetSummary();$('.spending-budget-section')?.classList.toggle('is-over',summary.limit!==null&&summary.used>summary.limit);$('#spending-label').textContent=summary.label;$('#spending-used').textContent=overviewCurrency(summary.used);$('#spending-used').classList.toggle('refund-amount',summary.used<0);$('#budget-caption').textContent=summary.caption;$('#budget-remaining').textContent=summary.remaining===null?'未設定':overviewCurrency(summary.remaining);$('#budget-limit').textContent=summary.limit===null?'':'／ '+overviewMoney(summary.limit);const percent=budgetUsage();$('#budget-percent').textContent=percent===null?'未設預算':Math.round(percent)+'%';$('#budget-marker').style.setProperty('--position',clamp(percent??100,0,100)+'%');$('#budget-all').hidden=budgetFocus<0;const canvas=$('#budget-canvas');canvas.setAttribute('aria-valuemax',buckets.length);canvas.setAttribute('aria-valuenow',budgetFocus+1);canvas.setAttribute('aria-valuetext',summary.label+' 已用 '+overviewCurrency(summary.used)+'，'+(summary.limit===null?'未設定分類預算':summary.caption+' '+overviewCurrency(summary.remaining)+'，額度 '+overviewCurrency(summary.limit)));}
function selectBudgetFocus(i){const next=clamp(i,-1,budgetBuckets().length-1);if(next===budgetFocus)return;budgetFocus=next;refreshBudget();dashboardCanvases.get('budget-canvas')?.render();}
function tileLabel(ctx,tile){
  const label=tile.kind==='holding'?tile.id:tile.name,width=Math.max(1,tile.w-14);let font=11;
  ctx.font='500 '+font+'px "Noto Sans TC",sans-serif';
  while(font>8&&ctx.measureText(label).width>width){font--;ctx.font='500 '+font+'px "Noto Sans TC",sans-serif';}
  if(ctx.measureText(label).width<=width)return{mode:'name',label,lines:[label],font};
  const lines=[];let line='';for(const char of label){if(line&&ctx.measureText(line+char).width>width){lines.push(line);line='';}line+=char;}if(line)lines.push(line);
  return{mode:'name',label,lines,font};
}
function allocationOpacity(selected){return assetIndex<0||selected?1:.32;}
function drawAllocationTile(ctx,tile,selected,index,p=1){
  const x=tile.x+2,y=tile.y+2,w=Math.max(0,tile.w-4),h=Math.max(0,tile.h-4);ctx.save();ctx.globalAlpha=p*allocationOpacity(selected);roundBox(ctx,x,y,w,h,5);ctx.fillStyle=tile.color;ctx.fill();if(selected){ctx.lineWidth=1.5;ctx.strokeStyle='#fffaf1';ctx.stroke();}ctx.clip();ctx.globalAlpha=p*(assetIndex<0||selected?1:.68);ctx.fillStyle=selected?'#fffdf5':palette.ink;const label=tileLabel(ctx,tile);
  ctx.font='500 '+label.font+'px "Noto Sans TC",sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';const lineHeight=label.font+3;
  label.lines.forEach((line,i)=>ctx.fillText(line,x+w/2,y+h/2+(i-(label.lines.length-1)/2)*lineHeight));ctx.restore();
}
function drawAllocation(ctx,w,h,p){
  const roots=splitTiles(rootAssetFacts(),0,0,w,h),holdings=splitTiles(allocationTransition?.children||assetFacts(),0,0,w,h),selected=assetFacts()[assetIndex],transition=allocationTransition;
  if(!transition){const data=assetMode!=='assets'?holdings:roots;data.forEach((t,i)=>drawAllocationTile(ctx,t,selected?.id===t.id,i));}
  else{const opening=transition.direction==='open',progress=opening?p:1-p,grow=clamp(progress/.65,0,1),reveal=clamp((progress-.55)/.45,0,1),origin=transition.origin;
    roots.filter(t=>t.id!==allocationParent?.id).forEach((t,i)=>drawAllocationTile(ctx,t,false,i,1-grow));
    if(origin&&reveal<1){const tile={...origin,x:origin.x*(1-grow),y:origin.y*(1-grow),w:origin.w+(w-origin.w)*grow,h:origin.h+(h-origin.h)*grow};drawAllocationTile(ctx,tile,true,0,1-reveal);}
    if(reveal>0)holdings.forEach((t,i)=>drawAllocationTile(ctx,t,assetMode!=='assets'&&selected?.id===t.id,i,reveal));
  }
  if(!assetFacts().length){ctx.fillStyle=palette.muted;ctx.font='11px "Noto Sans TC",sans-serif';ctx.textAlign='center';ctx.fillText(assetMode==='account'?'暫無帳戶':'暫無資產',w/2,h/2);}if(p===1)allocationTransition=null;
}
function allocationOrigin(){const w=dashboardCanvases.get('allocation-canvas')?.width()||300;return splitTiles(rootAssetFacts(),0,0,w,ALLOCATION_HEIGHT).find(t=>t.id===(allocationParent?.id||assetFacts()[assetIndex]?.id));}
function refreshAllocation(){ $('#allocation-status').textContent=allocationStatus();$('#allocation-status').hidden=assetMode==='assets';$('#allocation-context').textContent=allocationContext();selectAsset(assetIndex,false);dashboardCanvases.get('allocation-canvas')?.render(true);}
function openAllocation(){const a=assetFacts()[assetIndex];if(assetMode!=='assets'||!a)return;allocationParent=a;const origin=allocationOrigin();assetMode=a.kind==='investment'?'holdings':'account';assetIndex=-1;assetPinnedIndex=-1;allocationTransition={direction:'open',origin,children:assetFacts()};refreshAllocation();}
function openInvestment(){if(assetMode==='assets'&&assetFacts()[assetIndex]?.kind==='investment')openAllocation();}
function backToAssets(){if(assetMode==='assets')return;const children=assetFacts(),origin=allocationOrigin();assetMode='assets';assetIndex=-1;assetPinnedIndex=-1;allocationTransition={direction:'close',origin,children};refreshAllocation();}

const DAILY_WINDOW=7;
function dailyWeekStart(day){const date=new Date(month+'-'+String(day).padStart(2,'0')+'T00:00:00Z');return day-1-(date.getUTCDay()+6)%7;}
function dailyWeekSlots(start=dailyStart){const facts=dailyFacts();return Array.from({length:DAILY_WINDOW},(_,i)=>{const date=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5))-1,start+i+1)),key=date.toISOString().slice(0,10),day=date.getUTCDate(),inMonth=key.startsWith(month);return inMonth?{...facts[day-1],day,inMonth}:{date:key,day,inMonth,expense:null};});}
function dailyWeekLabel(start=dailyStart){const days=dailyWeekSlots(start),format=d=>Number(d.date.slice(5,7))+' / '+d.day;return format(days[0])+' 至 '+format(days[6]);}
function refreshDailyWeek(){const prev=$('#daily-prev'),next=$('#daily-next');$('#daily-week-label').textContent=dailyWeekLabel();$('#daily-week-total').textContent='本週 '+overviewCurrency(dailyWeekTotal());$('#daily-calendar').innerHTML=dailyCalendar();prev.disabled=dailyStart<=dailyWeekStart(1);next.disabled=dailyStart>=dailyWeekStart(monthDays());}
function moveDailyWeek(direction){const next=clamp(dailyStart+direction*DAILY_WINDOW,dailyWeekStart(1),dailyWeekStart(monthDays()));if(next===dailyStart)return;dailyStart=next;selectHeat(clamp(next+1,1,monthDays()));}
function dailyWeekTotal(start=dailyStart){return dailyWeekSlots(start).reduce((n,d)=>n+(d.inMonth?d.expense:0),0);}
function calendarAmount(value){const magnitude=Math.abs(value),text=magnitude>=10000?String(Number((magnitude/10000).toFixed(magnitude>=100000?0:2)))+'萬':overviewMoney(magnitude);return value<0?'+'+text:text;}
function dayActivityTags(day){const rows=dayTransactions(day),types=new Set(rows.map(t=>t.dividend||t.type==='investment'?'investment':t.type==='refund'?'expense':t.type));return [['expense','支','支出'],['income','收','收入'],['transfer','轉','轉帳'],['investment','投','投資']].filter(([type])=>types.has(type)).map(([type,label,name])=>`<span class="activity-tag activity-${type}" aria-label="${name}"></span>`).join('');}
function dailyCalendar(start=dailyStart){return dailyWeekSlots(start).map((d,i)=>{const active=d.inMonth&&d.day===heatDay;return `<button data-action="dash-day-select" data-day="${d.day}" class="calendar-day${active?' active':''}${d.inMonth?'':' outside'}" aria-pressed="${active}" ${d.inMonth?'':'disabled'} aria-label="${d.date}${d.inMonth?'，支出 '+overviewCurrency(d.expense)+'，'+dayTransactions(d.day).length+' 筆紀錄':'，不在本月'}"><span class="calendar-weekday">${['一','二','三','四','五','六','日'][i]}</span><strong class="calendar-date">${d.day}</strong><span class="day-activity-tags">${d.inMonth?dayActivityTags(d.day):''}</span></button>`;}).join('');}
function selectFlow(i){const data=flowFacts();flowIndex=clamp(i,0,data.length-1);const d=data[flowIndex];$('#flow-period').textContent=flowLabel(d);$('#flow-income').textContent=overviewCurrency(d.income);$('#flow-expense').textContent=overviewCurrency(d.expense);$('#flow-expense').classList.toggle('refund-amount',d.expense<0);$('#flow-balance').textContent=overviewCurrency(d.balance);$('#flow-balance').classList.toggle('negative',d.balance<0);$('#flow-balance').classList.toggle('positive',d.balance>=0);$('#growth-amount').textContent=overviewCurrency(d.assets);$('#growth-amount').hidden=!growthVisible;const c=$('#flow-canvas');c.setAttribute('aria-valuenow',flowIndex+1);c.setAttribute('aria-valuemax',data.length);c.setAttribute('aria-valuetext',d.label+' 收入 '+overviewCurrency(d.income)+' 支出 '+overviewCurrency(d.expense)+(growthVisible?' 淨資產 '+overviewCurrency(d.assets):''));$('#flow-axis').innerHTML=flowAxis();dashboardCanvases.get('flow-canvas')?.render();}
function selectAsset(i,redraw=true){const data=assetFacts();assetIndex=clamp(i,-1,Math.max(-1,data.length-1));const a=data[assetIndex];$('#asset-name').textContent=a?a.name:allocationName();$('#asset-amount').textContent=overviewCurrency(a?a.value:allocationTotal());$('#asset-amount').hidden=false;$('#allocation-all').hidden=assetIndex<0;$('#allocation-readout')?.classList.toggle('all-unselected',assetIndex<0);$('#allocation-canvas').setAttribute('aria-valuemax',data.length);$('#allocation-canvas').setAttribute('aria-valuenow',assetIndex+1);$('#allocation-canvas').setAttribute('aria-valuetext',(a?a.name:allocationName())+' '+overviewCurrency(a?a.value:allocationTotal()));if(redraw)dashboardCanvases.get('allocation-canvas')?.render();}
function selectHeat(day){const restoreFocus=document.activeElement?.closest?.('#daily-calendar');const next=clamp(day,1,monthDays());heatDay=next;const index=heatDay-1;if(index<dailyStart||index>=dailyStart+DAILY_WINDOW)dailyStart=dailyWeekStart(heatDay);$('#daily-details').innerHTML=dailyDetails(heatDay);refreshDailyWeek();if(restoreFocus)$('#daily-calendar').querySelector?.('[aria-pressed="true"]')?.focus({preventScroll:true});}
function plotKeyboard(canvas,getIndex,getLength,select,step=1,activate){canvas.addEventListener('keydown',e=>{const map={ArrowLeft:-1,ArrowRight:1,ArrowUp:-step,ArrowDown:step};if(e.key in map||e.key==='Home'||e.key==='End'){e.preventDefault();select(e.key==='Home'?0:e.key==='End'?getLength()-1:getIndex()+map[e.key]);}else if(activate&&(e.key==='Enter'||e.key===' ')){e.preventDefault();activate();}});}
function ringGesture(plot,hit,getIndex,select,onRelease,hooks){let down=false,lastX=0,lastY=0,pressX=0,pinned=getIndex(),timer=0,candidate=null;
  function clear(){if(timer)clearTimeout(timer);timer=0;candidate=null;}
  function hover(index){if(index===null){clear();select(pinned);return;}if(index===candidate||index===getIndex())return;clear();candidate=index;timer=setTimeout(()=>{timer=0;candidate=null;select(index);},85);}
  plot.cleanup(clear);
  plot.canvas.addEventListener('pointerdown',e=>{clear();down=true;pressX=e.clientX;lastX=e.clientX;lastY=e.clientY;plot.canvas.setPointerCapture?.(e.pointerId);const i=hit(e);if(i!==null){select(i);pinned=getIndex();}hooks?.press?.(e);});
  plot.canvas.addEventListener('pointermove',e=>{if(!down){if(e.pointerType==='mouse')hover(hit(e));return;}if(Math.hypot(e.clientX-lastX,e.clientY-lastY)<12)return;lastX=e.clientX;lastY=e.clientY;const i=hit(e);if(i!==null){select(i);pinned=getIndex();}});
  plot.canvas.addEventListener('pointerleave',()=>{clear();if(!down)select(pinned);});
  for(const event of ['pointerup','pointercancel','lostpointercapture'])plot.canvas.addEventListener(event,e=>{if(event==='pointerup'&&down&&onRelease){onRelease(e,pressX);pinned=getIndex();}hooks?.end?.(event);down=false;});
  return{pin(){clear();pinned=getIndex();}};
}
function clearBudgetOutside(e){if(budgetFocus<0||!dashboardCanvases.has('budget-canvas')||e.target?.closest?.('#budget-canvas, #spending-categories, #budget-all'))return;selectBudgetFocus(-1);budgetInteraction?.pin();}
document.addEventListener('pointerdown',clearBudgetOutside);
function attachBudget(){
  const budget=mountPlot('budget-canvas',BUDGET_HEIGHT,drawBudget,180);if(budget){refreshBudget();budgetInteraction=ringGesture(budget,e=>{const rect=budget.canvas.getBoundingClientRect();return budgetHit((e.clientX-rect.left)*budget.width()/rect.width,(e.clientY-rect.top)*BUDGET_HEIGHT/rect.height,budget.width(),BUDGET_HEIGHT);},()=>budgetFocus,selectBudgetFocus);plotKeyboard(budget.canvas,()=>budgetFocus+1,()=>budgetBuckets().length+1,i=>{selectBudgetFocus(i-1);budgetInteraction.pin();});budget.canvas.addEventListener('keyup',e=>{if(e.key==='Escape'){selectBudgetFocus(-1);budgetInteraction.pin();}});}
}
function attachDashboard(){
  const flow=mountPlot('flow-canvas',130,drawFlow);if(flow){plotGesture(flow.canvas,x=>selectFlow(Math.floor((x*flow.width()-26)/(flow.width()-56)*flowFacts().length)));plotKeyboard(flow.canvas,()=>flowIndex,()=>flowFacts().length,selectFlow);}
  refreshBudget();attachBudget();
  const allocation=mountPlot('allocation-canvas',ALLOCATION_HEIGHT,drawAllocation);if(allocation){selectAsset(assetIndex,false);const gesture=plotGesture(allocation.canvas,(x,y,e)=>{if(allocationTransition)return;const tiles=allocationTiles(allocation.width(),ALLOCATION_HEIGHT),px=x*allocation.width(),py=y*ALLOCATION_HEIGHT,index=tiles.findIndex(t=>px>=t.x&&px<=t.x+t.w&&py>=t.y&&py<=t.y+t.h);if(index>=0){const tile=tiles[index],i=assetFacts().findIndex(a=>a.id===tile.id&&a.kind===tile.kind);if(i>=0){selectAsset(i);if(e.pointerType!=='mouse')assetPinnedIndex=i;}}});allocation.canvas.addEventListener('click',()=>{if(gesture.dragged||gesture.held||allocationTransition)return;if(assetMode!=='assets')backToAssets();else openAllocation();});allocation.canvas.addEventListener('pointerleave',()=>{if(!allocationTransition)selectAsset(assetPinnedIndex);});plotKeyboard(allocation.canvas,()=>assetIndex+1,()=>assetFacts().length+1,i=>{assetPinnedIndex=i-1;selectAsset(i-1);},1,()=>dashboardAction('dash-asset-detail',{dataset:{}}));allocation.canvas.addEventListener('keyup',e=>{if(e.key==='Escape'){assetPinnedIndex=-1;selectAsset(-1);}});}

  dailyStart=dailyWeekStart(heatDay);selectHeat(heatDay);const calendar=$('#daily-calendar');calendar.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();selectHeat(e.key==='Home'?clamp(dailyStart+1,1,monthDays()):e.key==='End'?clamp(dailyStart+7,1,monthDays()):heatDay+(e.key==='ArrowRight'?1:-1));calendar.querySelector?.('[aria-pressed="true"]')?.focus();});
}
function dashboardAction(action,el){
  if(action==='dash-growth'){growthVisible=!growthVisible;el.setAttribute?.('aria-pressed',growthVisible);el.classList?.toggle('active',growthVisible);selectFlow(flowIndex);}
  if(action==='dash-flow-select')selectFlow(Number(el.dataset.index));
  if(action==='dash-asset-back')backToAssets();
  if(action==='dash-asset-all'){assetPinnedIndex=-1;selectAsset(-1);}
  if(action==='dash-day-select'){const day=Number(el.dataset.day);if(Number.isInteger(day)&&day>=1&&day<=monthDays())selectHeat(day);}
  if(action==='dash-budget-category'){const i=Number(el.dataset.index);selectBudgetFocus(i===budgetFocus?-1:i);budgetInteraction?.pin();}

  if(action==='dash-budget-all'){selectBudgetFocus(-1);budgetInteraction?.pin();}
  if(action==='dash-budget-edit')editBudget(state.budgets[0].id);
  if(action==='dash-flow-detail'){const d=flowFacts()[flowIndex];openLedgerContext({month:d.date.slice(0,7)});}
  if(action==='dash-receipt-prev')setDailyReceiptPage(dailyReceiptWindow().page-1);
  if(action==='dash-receipt-next')setDailyReceiptPage(dailyReceiptWindow().page+1);
  if(action==='dash-receipt-page-open')openDailyReceiptPages(el);
  if(action==='dash-receipt-page-select'){const index=Number(el.dataset.index);if(pickerCurrent()?.kind==='pagination'&&Number.isInteger(index)&&index>=0&&index<dailyReceiptWindow().pages){setDailyReceiptPage(index);backPickerPage();}}
  if(action==='dash-week-prev')moveDailyWeek(-1);
  if(action==='dash-week-next')moveDailyWeek(1);
  if(action==='dash-asset-detail'){if(assetMode!=='assets')backToAssets();else openAllocation();}
  if(action==='dash-day-detail'){openLedgerContext({month,dateFilter:month+'-'+String(heatDay).padStart(2,'0')});}
}

// Refresh raster text once the app font finishes loading.
document.fonts?.ready.then(()=>{for(const chart of dashboardCanvases.values())chart.render();});
